// ✅ IN C# (Creating a Thread is incredibly easy)

// 1. We start the main Process (The Console App)
Console.WriteLine("Main thread is running...");

// 2. We hire a background worker (A Thread) to do heavy lifting
Thread worker = new Thread(() => 
{
    Console.WriteLine("Background thread is downloading a file...");
});
worker.Start();

Console.WriteLine("Main thread is still responsive!");

// ❌ HOW TO CREATE A DEADLOCK IN C#
object lockA = new object();
object lockB = new object();

// Thread 1
lock (lockA)
{
    Thread.Sleep(100); // Wait a millisecond...
    lock (lockB) // Thread 1 freezes here forever
    {
        Console.WriteLine("Thread 1 got both locks");
    }
}

// Thread 2 (Running at the exact same time)
lock (lockB)
{
    Thread.Sleep(100); // Wait a millisecond...
    lock (lockA) // Thread 2 freezes here forever
    {
        Console.WriteLine("Thread 2 got both locks");
    }
}

// Why Virtual Memory Matters in .NET:
// A 32-bit process can only address 4GB of memory.
// A 64-bit process has a massive 8 Terabyte virtual memory limit.

// If your C# app allocates massive arrays and Physical RAM is full,
// the OS won't instantly crash with OutOfMemoryException.
// Instead, it silently pages memory to the SSD, making your app
// 10,000x slower. This is why memory profiling is critical.

