// ✅ SEMAPHORE (Limiting concurrency to 3)
// We allow a maximum of 3 threads to do this heavy work at once.
private SemaphoreSlim _bouncer = new SemaphoreSlim(3);

public async Task DownloadFileAsync()
{
    await _bouncer.WaitAsync(); // Bouncer lets me in (or makes me wait)
    try
    {
        await HeavyDownloadLogic();
    }
    finally
    {
        _bouncer.Release(); // I leave, bouncer lets the next guy in
    }
}
